'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),cp=require('node:child_process'),path=require('node:path'),C=require('./private-capture.cjs');
const PS='C:/Users/runge/.cache/codex-runtimes/codex-primary-runtime/dependencies/native/powershell/pwsh.exe';
function invoke(name,input,args=[]){return cp.spawnSync(PS,['-NoLogo','-NoProfile','-NonInteractive','-File',path.join(__dirname,name),...args],{input:input===null?undefined:JSON.stringify(input),cwd:__dirname,env:{...C.environment(process.env),SystemRoot:process.env.SystemRoot},encoding:null,shell:false,timeout:30000,maxBuffer:2*1024*1024,windowsHide:true});}
test('real SignedCms7.6.5 verifies synthetic in-memory P12 keypair/profile and rejects wrong password/reference/tampered CMS',()=>{const made=invoke('crypto-fixtures.ps1',null,['--synthetic']);assert.equal(made.status,0);assert.equal(made.stderr.length,0);const fixture=JSON.parse(made.stdout.toString('utf8')),ok=invoke('signer-check.ps1',fixture);assert.equal(ok.status,0,ok.stdout.toString());assert.equal(ok.stderr.length,0);const result=JSON.parse(ok.stdout);assert.equal(result.certificateKeyPairVerified,true);assert.equal(result.profileCmsVerified,true);assert.equal(result.profileEntitlementsVerified,true);for(const [key,value]of [['password','wrong'],['certificateSerialSha256','0'.repeat(64)],['profileUuidSha256','0'.repeat(64)],['cms',Buffer.from('bad').toString('base64')]]){const r=invoke('signer-check.ps1',{...fixture,[key]:value});assert.equal(r.status,1);assert.deepEqual(JSON.parse(r.stdout),{protectedSignerValidation:false});assert.equal(r.stdout.includes(Buffer.from(fixture.password)),false);}made.stdout.fill(0);});
